"""Art direction phase 2: the bestiary's briefs under docs/ART_DIRECTION.md (moonlit ink and wash, one BLOOD accent).
Written into art/manifest.json as `brief3` (python3 art/phase2_briefs.py); make_prompts.build3 prefers it over `description`.
Each keeps the v2 brief's tag (ART.md: the tag lives in the silhouette); colours are the guide's palette names."""
import json
from pathlib import Path

GOB = "cold DUSK-green goblin skin (a desaturated grey-green inside the DUSK/MOON family, NOT bright green), long pointed ears with MIST rims, small glinting BONE eyes, INK shadow"
DEAD = ("DEATH POSE of {who}, the same character as its living boss sprite: fallen and lying still, seen from the same high "
        "three-quarter camera, the body stretched out HORIZONTALLY (on its side or back, head to the right), limbs slack, its weapon "
        "dropped beside it, crown knocked askew. It must read as 'the boss, dead' — a recognisable body, not a smear: keep its "
        "signature shapes and colours, the living colours sunk a step toward UMBRA, moonlight on the top edges only. Wide and low: "
        "the body spans most of the canvas width and about a third of its height. A small BLOOD spatter near the wound is allowed; "
        "NO blood pool, no floor, no shadow.")

