DEAD_WHO = {
 "boss_goblin_warlord": "the GOBLIN WARLORD (a towering gaunt goblin king, cold DUSK-green skin, a spiked iron crown, a tattered BLOOD-and-INK mantle, a huge cleaver)",
 "boss_bloat_mother": "the BLOAT MOTHER (a huge sac of pale teal-green gas, a crown of BONE spines, budding bloat-buds) — collapsed and deflated, sagging flat",
 "boss_lich": "the LICH (a gaunt skeleton king in INK-and-DUSK robes, a BONE skull-crown, a skull-topped staff, the cold flame guttered out)",
 "boss_foundry_master": "the FOUNDRY MASTER (a colossal riveted iron forge-lord, anvil chest, leather apron, spiked iron crown, a giant hammer; the EMBER seams cooling to CLOT)",
 "boss_lurker_queen": "the LURKER QUEEN (a huge pallid eyeless matriarch, bone-spine crown, four long thin arms)",
 "boss_mirror_king": "the MIRROR KING (a tall figure of dark mirror with MIST edge light, a spiked GILT crown, a mirror sceptre) — the mirror body cracked across",
}
for k, who in DEAD_WHO.items():
    B[f"{k}_dead"] = DEAD.format(who=who)


def main() -> None:
    p = Path(__file__).resolve().parent / "manifest.json"
    m = json.loads(p.read_text())
    n = 0
    for a in m["assets"]:
        if a["id"] in B:
            a["brief3"] = B[a["id"]]; n += 1
    p.write_text(json.dumps(m, indent=2, ensure_ascii=False) + "\n")
    print(f"brief3: {n} foes")


if __name__ == "__main__":
    main()
